import{_ as t,c as r,o as a,af as d}from"./chunks/framework.DeiWFBFB.js";const m=JSON.parse('{"title":"Samples","description":"","frontmatter":{},"headers":[],"relativePath":"guide/samples.md","filePath":"guide/samples.md","lastUpdated":1791988773000}'),s={name:"guide/samples.md"};function o(i,e,n,c,l,p){return a(),r("div",null,e[0]||(e[0]=[d('<h1 id="samples" tabindex="-1">Samples <a class="header-anchor" href="#samples" aria-label="Permalink to &quot;Samples&quot;">​</a></h1><p>The <a href="https://github.com/picardjs/samples" target="_blank" rel="noreferrer">samples repository</a> shows Picard.js in all kinds of applications: single-page apps, server-side rendering with streaming, static site generators, backends written in other languages, desktop and mobile apps, a browser extension, and unit tests. Every sample has a README explaining what Picard.js does there and exactly where it is integrated.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Looking for a starting point? Pick the sample closest to your stack, then read the matching integration guide: <a href="./integrations/spa">Single-Page Apps</a>, <a href="./integrations/ssr">Server-Side Rendering</a>, <a href="./integrations/apps">Desktop &amp; Mobile Apps</a>, or <a href="./integrations/testing">Testing</a>.</p></div><h2 id="rendering-in-the-browser" tabindex="-1">Rendering in the Browser <a class="header-anchor" href="#rendering-in-the-browser" aria-label="Permalink to &quot;Rendering in the Browser&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sample</th><th>Stack</th><th>Where Picard.js is integrated</th></tr></thead><tbody><tr><td><a href="https://github.com/picardjs/samples/tree/main/angular/spa" target="_blank" rel="noreferrer">Angular SPA</a></td><td>Angular 19</td><td><code>main.ts</code> next to <code>bootstrapApplication</code>, <code>CUSTOM_ELEMENTS_SCHEMA</code></td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/react/spa" target="_blank" rel="noreferrer">React SPA</a></td><td>React 19, Vite</td><td><code>main.tsx</code>, JSX typing for <code>pi-component</code></td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/svelte/spa" target="_blank" rel="noreferrer">Svelte SPA</a></td><td>Svelte 5, Vite</td><td><code>main.ts</code>, no configuration needed</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/vue/spa" target="_blank" rel="noreferrer">Vue SPA</a></td><td>Vue 3, Vite</td><td><code>main.ts</code>, <code>isCustomElement</code></td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/rsbuild/mf" target="_blank" rel="noreferrer">Rsbuild</a></td><td>Rsbuild 2, Module Federation</td><td>a Module Federation host sharing its remotes with Picard.js</td></tr></tbody></table><h2 id="rendering-on-the-server" tabindex="-1">Rendering on the Server <a class="header-anchor" href="#rendering-on-the-server" aria-label="Permalink to &quot;Rendering on the Server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sample</th><th>Stack</th><th>Where Picard.js is integrated</th></tr></thead><tbody><tr><td><a href="https://github.com/picardjs/samples/tree/main/angular/ssr" target="_blank" rel="noreferrer">Angular SSR</a></td><td>Angular 19, Express</td><td><code>server.ts</code> decorates the response of the Angular engine</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/aspnet/ssr" target="_blank" rel="noreferrer">ASP.NET Core</a></td><td>.NET 10</td><td>a middleware calls a decorator service</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/bun/ssr" target="_blank" rel="noreferrer">Bun</a></td><td>Bun</td><td><code>Bun.serve</code> routes, incl. Native Federation on the server</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/deno/ssr" target="_blank" rel="noreferrer">Deno</a></td><td>Deno 2</td><td><code>Deno.serve</code> with an <code>npm:</code> import</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/turbo/ssr" target="_blank" rel="noreferrer">Hotwire Turbo</a></td><td>Express, Turbo 8</td><td>each route decorates its page; Turbo swaps the <code>body</code></td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/htmx/ssr" target="_blank" rel="noreferrer">htmx</a></td><td>Python, FastAPI</td><td>a middleware decorates pages and htmx fragments via a decorator service</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/next/ssr" target="_blank" rel="noreferrer">Next.js</a></td><td>Next.js 16</td><td>async Server Components in <code>Suspense</code> (streaming)</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/nuxt/ssr" target="_blank" rel="noreferrer">Nuxt</a></td><td>Nuxt 4</td><td>a Nitro plugin (<code>render:html</code>, <code>render:response</code>)</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/react-router/ssr" target="_blank" rel="noreferrer">React Router</a></td><td>React Router 8</td><td>loaders return <code>decorate</code> promises, rendered with <code>Await</code> (streaming)</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/solid/ssr" target="_blank" rel="noreferrer">SolidStart</a></td><td>SolidStart 2</td><td>a middleware; a signal bound to <code>data</code></td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/sveltekit/ssr" target="_blank" rel="noreferrer">SvelteKit</a></td><td>SvelteKit 3</td><td><code>transformPageChunk</code> in <code>hooks.server.ts</code></td></tr></tbody></table><h2 id="rendering-at-build-time" tabindex="-1">Rendering at Build Time <a class="header-anchor" href="#rendering-at-build-time" aria-label="Permalink to &quot;Rendering at Build Time&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sample</th><th>Stack</th><th>Where Picard.js is integrated</th></tr></thead><tbody><tr><td><a href="https://github.com/picardjs/samples/tree/main/astro/ssg" target="_blank" rel="noreferrer">Astro</a></td><td>Astro 7</td><td>a middleware and a static endpoint for the islands script</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/hugo/ssg" target="_blank" rel="noreferrer">Hugo</a></td><td>Hugo</td><td>a decorator CLI runs after <code>hugo</code></td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/qwik/ssg" target="_blank" rel="noreferrer">Qwik</a></td><td>Qwik City 1</td><td>a <code>server$</code> function in a component</td></tr></tbody></table><h2 id="desktop-mobile-and-other-environments" tabindex="-1">Desktop, Mobile, and Other Environments <a class="header-anchor" href="#desktop-mobile-and-other-environments" aria-label="Permalink to &quot;Desktop, Mobile, and Other Environments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sample</th><th>Stack</th><th>Where Picard.js is integrated</th></tr></thead><tbody><tr><td><a href="https://github.com/picardjs/samples/tree/main/extension/mv3" target="_blank" rel="noreferrer">Browser extension</a></td><td>Chromium, Manifest V3</td><td>browser script and micro frontends bundled into the extension</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/capacitor/app" target="_blank" rel="noreferrer">Capacitor</a></td><td>Capacitor 8</td><td><code>picard-js/client</code> with a feed combining bundled and remote micro frontends</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/electron/client" target="_blank" rel="noreferrer">Electron</a></td><td>Electron 35</td><td>browser script in the renderer</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/react-native/app" target="_blank" rel="noreferrer">React Native</a></td><td>Expo 57</td><td>a WebView on iOS / Android, the DOM on the web</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/tauri/client" target="_blank" rel="noreferrer">Tauri</a></td><td>Tauri 2</td><td><code>main.ts</code> in the webview</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/vitest/testing" target="_blank" rel="noreferrer">Vitest</a></td><td>Vitest 5, jsdom, happy-dom</td><td>the page under test starts <code>picard-js/client</code></td></tr></tbody></table><h2 id="the-demo-micro-frontends" tabindex="-1">The Demo Micro Frontends <a class="header-anchor" href="#the-demo-micro-frontends" aria-label="Permalink to &quot;The Demo Micro Frontends&quot;">​</a></h2><p>All samples use the <code>picard-demos</code> feed (<code>https://feed.piral.cloud/api/v1/microfrontends/picard-demos</code>). Its micro frontends are framework-less on purpose, and each one uses a different format:</p><table tabindex="0"><thead><tr><th>Micro frontend</th><th>Format</th><th>Component</th><th>Rendering</th></tr></thead><tbody><tr><td><code>mf-simple-html</code></td><td>Module Federation</td><td><code>column</code></td><td>client only</td></tr><tr><td><code>nfsimplehtml</code></td><td>Native Federation</td><td><code>column</code></td><td>client only</td></tr><tr><td><code>pi-simple-html</code></td><td>Pilet</td><td><code>counter</code></td><td>client only</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/shared/pi-ssr-html" target="_blank" rel="noreferrer"><code>pi-ssr-html</code></a></td><td>Pilet</td><td><code>ssr-counter</code></td><td>server and client (hydrated)</td></tr><tr><td><a href="https://github.com/picardjs/samples/tree/main/shared/nf-ssr-html" target="_blank" rel="noreferrer"><code>nf-ssr-html</code></a></td><td>Native Federation</td><td><code>ssr-likes</code></td><td>server and client (hydrated)</td></tr></tbody></table><p>The sources of the two server-renderable micro frontends are part of the samples repository. They&#39;re a compact reference for writing a <a href="./../api/lifecycle/">component lifecycle</a> that supports <code>stringify</code>, hydration, and <code>update</code>.</p><p>The repository also contains <a href="https://github.com/picardjs/samples/tree/main/shared/picard-decorator" target="_blank" rel="noreferrer"><code>picard-decorator</code></a>, a small Node.js tool that renders micro frontends into HTML produced by something other than a Node.js server. It runs as an HTTP service or as a build step.</p><h2 id="examples-in-the-picard-js-repository" tabindex="-1">Examples in the Picard.js Repository <a class="header-anchor" href="#examples-in-the-picard-js-repository" aria-label="Permalink to &quot;Examples in the Picard.js Repository&quot;">​</a></h2><p>The <a href="https://github.com/picardjs/picard/tree/develop/examples" target="_blank" rel="noreferrer">Picard.js repository</a> has more examples, which focus on individual features rather than on frameworks:</p><ul><li><a href="https://github.com/picardjs/picard/tree/develop/examples/01-static-page" target="_blank" rel="noreferrer">static pages</a>, <a href="https://github.com/picardjs/picard/tree/develop/examples/02-static-page-feed" target="_blank" rel="noreferrer">with a feed</a>, <a href="https://github.com/picardjs/picard/tree/develop/examples/03-static-page-slots" target="_blank" rel="noreferrer">with slots</a>, and <a href="https://github.com/picardjs/picard/tree/develop/examples/05-static-page-with-routing" target="_blank" rel="noreferrer">with routing</a></li><li><a href="https://github.com/picardjs/picard/tree/develop/examples/06-static-page-single-spa" target="_blank" rel="noreferrer">single-spa components</a> and <a href="https://github.com/picardjs/picard/tree/develop/examples/10-dependencies-sharing" target="_blank" rel="noreferrer">dependency sharing across formats</a></li><li><a href="https://github.com/picardjs/picard/tree/develop/examples/08-ssr-tractor" target="_blank" rel="noreferrer">server-side rendering</a>, <a href="https://github.com/picardjs/picard/tree/develop/examples/16-ssr-islands" target="_blank" rel="noreferrer">islands</a>, and <a href="https://github.com/picardjs/picard/tree/develop/examples/14-slot-capabilities" target="_blank" rel="noreferrer">slot</a> / <a href="https://github.com/picardjs/picard/tree/develop/examples/15-component-capabilities" target="_blank" rel="noreferrer">component capabilities</a></li></ul>',19)]))}const g=t(s,[["render",o]]);export{m as __pageData,g as default};
